(() => {
  "use strict";
  const BL = window.BL;
  const { makeVox, voxelGeometry } = BL.models;
  const { createNode, addChild } = BL.scene;
  const ORANGE = "#ff9a1f", ORANGE_CORE = "#fff1c4";
  const CARIBBEAN = "#1fb6cc";
  const speckle = (x, y, z) => {
    let n = Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(z, 83492791);
    n = Math.imul(n ^ (n >>> 13), 1274126177);
    return ((n ^ (n >>> 16)) >>> 0) % 100;
  };
  const DIRS = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
  const smooth = (src) => {
    const out = makeVox();
    src.each((x, y, z, c) => {
      for (let o = 0; o < 8; o++) {
        const s = [o & 1 ? 1 : -1, o & 2 ? 1 : -1, o & 4 ? 1 : -1];
        let cut = 0;
        DIRS.forEach(([a, b, d], i) => { if (!src.has(x + a * s[i], y + b * s[i], z + d * s[i]) && src.has(x - a * s[i], y - b * s[i], z - d * s[i])) cut++; });
        if (cut < 2) out.set(2 * x + (o & 1), 2 * y + (o >> 1 & 1), 2 * z + (o >> 2), c);
      }
    });
    return out;
  };
  const KOBE_PALETTE = ["#4a35c8", "#3b28a6", "#ff7a2a", "#ff4f9a", "#2fd6c8", "#ffd23f", "#f6ecd9", "#15100c", "#3a2416", "#3f8fe8", "#8fd0ff"];
  const [VIOLET, INDIGO, TANGERINE, ROSE, TURQUOISE, SUN, CREAM, JET, EYE, BEAD, BEAD_LIGHT] = KOBE_PALETTE.map((_, i) => i);
  const KOBE_GLOW = { [BEAD]: 0.9, [BEAD_LIGHT]: 1.2 };
  let kobe = null;
  const kobeVox = () => {
    if (kobe) return kobe;
    const v = makeVox(), coat = (x, y, z) => (speckle(x, y, z) < 20 ? INDIGO : VIOLET);
    const bloom = (set, petal, corner) => {
      set(0, 0, SUN);
      for (const [a, b] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { set(a, b, petal); set(2 * a, 2 * b, petal); }
      for (const [a, b] of [[1, 1], [-1, 1], [1, -1], [-1, -1]]) set(a, b, corner);
    };
    for (const x0 of [-3, 2]) for (const z0 of [-6, 3]) {
      v.fill(x0, x0 + 1, 1, 3, z0, z0 + 1, (x, y) => [TURQUOISE, TANGERINE, ROSE][y - 1]);
      v.fill(x0, x0 + 1, 0, 0, z0, z0 + 1, SUN);
    }
    v.fill(-3, 3, 4, 10, -6, 4, coat);
    for (const x of [-3, 3]) for (const y of [4, 10]) for (let z = -6; z <= 4; z++) v.del(x, y, z);
    for (const x of [-3, 3]) {
      bloom((dz, dy, c) => v.set(x, 7 + dy, -4 + dz, c), ROSE, TANGERINE);
      bloom((dz, dy, c) => v.set(x, 7 + dy, 2 + dz, c), TURQUOISE, SUN);
      v.set(x, 6, -1, TURQUOISE); v.set(x, 7, -1, SUN); v.set(x, 8, -1, TURQUOISE);
    }
    for (let z = -6; z <= 4; z++) {
      v.set(0, 10, z, z % 2 ? ROSE : SUN);
      if (z % 2 === 0) { v.set(-2, 10, z, TURQUOISE); v.set(2, 10, z, TURQUOISE); }
    }
    v.fill(-2, 2, 4, 9, 4, 4, TANGERINE);
    bloom((dx, dy, c) => { if (Math.abs(dx) < 2) v.set(dx, 7 + dy, 4, c); }, ROSE, SUN);
    v.fill(-2, 2, 5, 9, -6, -6, TURQUOISE);
    bloom((dx, dy, c) => { if (Math.abs(dx) < 2) v.set(dx, 7 + dy, -6, c); }, ROSE, TANGERINE);
    v.fill(-2, 2, 11, 11, 1, 4, coat);
    for (let x = -3; x <= 3; x++) for (let z = 0; z <= 5; z++) if (Math.abs(x) === 3 || z === 0 || z === 5) v.set(x, 11, z, (x + z) % 2 ? BEAD : BEAD_LIGHT);
    v.fill(-3, 3, 12, 17, 1, 7, coat);
    for (const x of [-3, 3]) for (const y of [12, 17]) for (let z = 1; z <= 7; z++) v.del(x, y, z);
    bloom((dx, dz, c) => { if (Math.abs(dx) < 2 && Math.abs(dz) < 2) v.set(dx, 17, 4 + dz, c); }, ROSE, TURQUOISE);
    v.fill(-1, 1, 12, 14, 8, 9, CREAM);
    v.set(0, 14, 9, JET); v.set(0, 12, 9, ROSE);
    v.fill(-2, 2, 12, 12, 7, 7, CREAM);
    v.fill(-1, 1, 15, 16, 7, 7, TANGERINE);
    v.set(0, 16, 7, SUN); v.set(0, 17, 7, TURQUOISE); v.set(-1, 17, 7, ROSE); v.set(1, 17, 7, ROSE);
    for (const s of [-1, 1]) {
      v.fill(Math.min(2 * s, 3 * s), Math.max(2 * s, 3 * s), 14, 15, 7, 7, EYE);
      v.set(2 * s, 15, 7, CREAM);
      v.set(2 * s, 16, 7, TURQUOISE); v.set(3 * s, 16, 7, TURQUOISE);
      v.set(2 * s, 13, 7, TANGERINE); v.set(3 * s, 13, 7, ROSE);
      v.set(3 * s, 15, 3, TURQUOISE); v.set(3 * s, 14, 4, SUN); v.set(3 * s, 14, 2, ROSE); v.set(3 * s, 15, 5, TANGERINE);
      [[1, 3], [1, 4], [2, 4], [2, 4], [3, 5], [4, 4]].forEach(([a, b], i) => {
        for (let x = a; x <= b; x++) {
          v.set(x * s, 18 + i, 3, i === 5 ? SUN : VIOLET);
          v.set(x * s, 18 + i, 4, i === 5 ? SUN : x > a && x < b ? TANGERINE : ROSE);
        }
      });
    }
    v.fill(0, 0, 8, 11, -7, -7, (x, y) => [ROSE, TANGERINE, SUN, TURQUOISE][y - 8]);
    v.set(0, 12, -6, ROSE); v.set(0, 12, -5, SUN);
    return (kobe = smooth(v));
  };
  const HAT_PALETTE = ["#d8c08a", "#c4a768", "#e8d7a8", "#b39656", "#7a5a3a", "#5e432a", "#c4783a", "#8a4f22", "#d99a55", "#f0e2c0"];
  const [STRAW, STRAW_DARK, STRAW_LIGHT, STRAW_OLD, BAND, BAND_DARK, VANE, QUILL, VANE_LIGHT, TIP] = HAT_PALETTE.map((_, i) => i);
  let hat = null;
  const hatVox = () => {
    if (hat) return hat;
    const v = makeVox();
    const straw = (x, y, z) => {
      const n = speckle(x, y, z);
      return n < 8 ? STRAW_OLD : ((x >> 1) + (z >> 1) + y) & 1 ? (n < 60 ? STRAW : STRAW_LIGHT) : n < 70 ? STRAW_DARK : STRAW;
    };
    for (let y = 18; y <= 26; y++) {
      const inset = y >= 26 ? 3 : y >= 25 ? 1 : 0;
      for (let x = -2 + inset; x <= 15 - inset; x++) for (let z = -2 + inset; z <= 13 - inset; z++) {
        const sideX = x === -2 + inset || x === 15 - inset, sideZ = z === -2 + inset || z === 13 - inset;
        if (sideX && sideZ && y >= 24 || y < 25 && !sideX && !sideZ) continue;
        v.set(x, y, z, y === 20 ? BAND_DARK : y === 21 ? BAND : straw(x, y, z));
      }
    }
    const cx = 7, cz = 6;
    for (let x = -14; x <= 28; x++) for (let z = -14; z <= 26; z++) {
      const d = Math.hypot(x - cx, z - cz) + (speckle(x >> 1, 7, z >> 1) % 3) * 0.35;
      if (d > 16.6 || (x >= -2 && x <= 15 && z >= -2 && z <= 13)) continue;
      const y = d > 15 ? 16 : d > 12.5 ? 17 : 18;
      v.set(x, y, z, straw(x, y, z));
      if (d > 14.6 && speckle(x, 3, z) < 22 && !(z > 14 && Math.abs(x - cx) < 9)) {
        v.set(x, y - 1, z, straw(x, 1, z));
        if (speckle(x, 5, z) < 45) v.set(x, y - 2, z, straw(x, 2, z));
        if (speckle(x, 9, z) < 15) v.set(x, y - 3, z, STRAW_OLD);
      }
    }
    for (let i = 0; i <= 13; i++) {
      const y = 20 + i, zc = 7 - Math.round(i * 0.6), w = i < 2 ? 0 : i < 4 || i > 10 ? 1 : 2, x = 16 + (i > 7 ? 1 : 0);
      for (let d = -w; d <= w; d++) for (const side of [x, 13 - x]) v.set(side, y, zc + d, i > 10 ? TIP : d === 0 ? QUILL : speckle(x, y, zc + d) < 35 ? VANE_LIGHT : VANE);
    }
    return (hat = v);
  };
  const STICKERS = ["#d8322a", "#f2c230", "#2f9a48", "#f4df3a", "#7a3fa8", "#f4f1e6", "#17130f"];
  const GUITAR_PALETTE = ["#e3b872", "#cf9d55", "#5a2e1c", "#2e1a12", "#120b07", "#efe3c4", "#dcdcd2", "#c9c3b4", "#8a4f22", "#7a4a2a", "#6b3822", ...STICKERS];
  const [TOP, GRAIN, SIDE, DARK, HOLE, BONE, STEEL, TUNER, ROSETTE, NECK, BACK, S_RED, S_GOLD, S_GREEN, S_YELLOW, S_PURPLE, S_WHITE, S_BLACK] = GUITAR_PALETTE.map((_, i) => i);
  const BODY = [3, 4, 4, 4, 3, 3, 4, 5, 5, 5, 5, 4, 3], BODY_Y = 8, BRIDGE_Y = 17;
  let guitar = null;
  const guitarVox = () => {
    if (guitar) return guitar;
    const v = makeVox();
    v.fill(-2, 2, -5, -2, -1, 0, DARK);
    for (const y of [-5, -3]) for (const side of [-1, 1]) { v.set(3 * side, y, -1, TUNER); v.set(side, y, -2, STEEL); }
    v.fill(-1, 1, -1, BODY_Y - 1, 0, 1, NECK);
    v.fill(-1, 1, 0, BODY_Y + 1, -1, -1, DARK);
    for (const y of [3, 6, 9]) v.set(0, y, -1, STEEL);
    v.fill(-1, 1, -1, -1, -2, -1, BONE);
    for (const x of [-1, 1]) v.fill(x, x, 0, BRIDGE_Y - 1, -2, -2, STEEL);
    for (let r = 0; r < BODY.length; r++) {
      const w = BODY[r], y = BODY_Y + r;
      for (let x = -w; x <= w; x++) {
        const edge = Math.abs(x) === w || r === 0 || r === BODY.length - 1 || Math.abs(x) > BODY[r - 1] || Math.abs(x) > BODY[r + 1];
        v.set(x, y, 0, edge ? BONE : (x + 5) % 3 === 0 ? GRAIN : TOP);
        v.fill(x, x, y, y, 1, 3, SIDE);
        v.set(x, y, 4, BACK);
      }
    }
    for (const [r, hole, ring] of [[2, -1, 1], [3, 1, 2], [4, 2, 3], [5, 2, 3], [6, 1, 2], [7, -1, 1]]) {
      const y = BODY_Y + r;
      for (let x = -ring; x <= ring; x++) v.set(x, y, 0, Math.abs(x) <= hole ? HOLE : ROSETTE);
    }
    v.fill(-3, 3, BRIDGE_Y, BRIDGE_Y + 1, -1, -1, DARK);
    v.fill(-2, 2, BRIDGE_Y, BRIDGE_Y, -2, -2, BONE);
    for (const [x, y] of [[-3, 9], [-2, 9], [-2, 10], [-1, 10], [-1, 11], [0, 11]]) v.set(x, y, 4, S_WHITE);
    for (let x = 1; x <= 3; x++) for (let y = 9; y <= 11; y++) v.set(x, y, 4, x === 2 && y === 10 ? S_BLACK : S_WHITE);
    v.set(-1, 13, 4, S_RED); v.set(0, 13, 4, S_BLACK);
    for (let x = -4; x <= 4; x++) { v.set(x, 15, 4, x < -1 ? S_RED : x < 2 ? S_GOLD : S_GREEN); v.set(x, 16, 4, S_BLACK); }
    for (let x = -4; x <= 1; x++) { v.set(x, 17, 4, S_YELLOW); v.set(x, 18, 4, x % 2 ? S_PURPLE : S_YELLOW); }
    v.set(3, 17, 4, S_GOLD); v.set(4, 17, 4, S_GOLD); v.set(3, 18, 4, S_WHITE); v.set(4, 18, 4, S_BLACK);
    v.set(-3, 19, 4, S_WHITE); v.set(-2, 19, 4, S_PURPLE); v.set(0, 19, 4, S_RED); v.set(1, 19, 4, S_WHITE); v.set(3, 19, 4, S_RED);
    for (let x = 1; x <= 3; x++) v.set(x, 19, 0, x === 2 ? S_PURPLE : S_YELLOW);
    return (guitar = v);
  };
  const SASH_PALETTE = ["#b3443b", "#93342d", "#c4665a", "#e4dac1", "#d0c4a6", "#eee6d1", "#4f7f4a", "#3d6639", "#70996a", "#40599a", "#31477d", "#5b74ab", "#d3a08f", "#a9b88f", "#44706f", "#6e4526", "#55331b", "#8a5a34", "#c9a878", "#c4c8cc", "#8e9499", "#eef1f3"];
  const [RED, , , WHITE, , , GREEN, , , BLUE, , , PINK, SAGE, TEAL, LEATHER, LEATHER_DARK, LEATHER_LIGHT, STITCH, SILVER, SILVER_DARK, SILVER_LIGHT] = SASH_PALETTE.map((_, i) => i);
  let sash = null;
  const sashVox = () => {
    if (sash) return sash;
    const v = makeVox();
    const inside = (x, z, grow) => Math.abs(x) <= 14 + grow && Math.abs(z + 0.5) <= 9.5 + grow && Math.abs(x) + Math.abs(z + 0.5) <= 20.5 + 2 * grow;
    const cloth = (x, y, z) => {
      const n = speckle(x, y, z), top = 7.6 + 0.9 * Math.sin(x * 0.45 + z * 0.3), low = 0.1 + 0.8 * Math.sin(x * 0.38 - z * 0.33 + 2);
      const wash = Math.sin(x * 0.3 + y * 0.9 + z * 0.25) + Math.sin(z * 0.4 - x * 0.17 + y * 0.5 + 1.3) + (n / 100 - 0.5) * 1.4;
      if (Math.abs(y - top) < 0.5 && n % 2) return PINK;
      if (Math.abs(y - low) < 0.5 && n % 2) return TEAL;
      if (y === 2 && n % 3 === 0 || y === 6 && n % 5 === 0) return SAGE;
      return (y > top ? RED : y > 4 ? WHITE : y > low ? GREEN : BLUE) + (wash < -0.8 ? 1 : wash > 0.8 ? 2 : 0);
    };
    const hide = (x, y, z) => { const n = speckle(x, y, z); return y !== 4 ? LEATHER_DARK : (x + z + 40) % 3 === 0 ? STITCH : n < 20 ? LEATHER_LIGHT : LEATHER; };
    for (let x = -15; x <= 15; x++) for (let z = -11; z <= 10; z++) {
      if (inside(x, z, 0) && !inside(x, z, -1)) for (let y = -1; y <= 9; y++) if (y < 3 || y > 5) v.set(x, y, z, cloth(x, y, z));
      if (inside(x, z, 1) && !inside(x, z, 0)) for (let y = 3; y <= 5; y++) v.set(x, y, z, hide(x, y, z));
    }
    for (let x = -3; x <= 3; x++) for (let y = 2; y <= 6; y++) {
      const rim = Math.abs(x) === 3 || y === 2 || y === 6;
      if (rim) v.set(x, y, 11, y === 6 ? SILVER_LIGHT : y === 2 || x === 3 ? SILVER_DARK : SILVER);
      else if (y === 4 && x >= 0) v.set(x, y, 11, SILVER_DARK);
    }
    for (let x = 8; x <= 12; x++) for (let y = -2; y <= 9; y++) {
      const star = y % 2 === 0 ? x % 4 === 0 : x === 10;
      v.set(x, y, 11, star ? WHITE + speckle(x, y, 3) % 2 : BLUE + speckle(x, y, 11) % 3);
    }
    return (sash = v);
  };
  const HEAD_PALETTE = ["#d99a74", "#3b3430", "#322c29", "#8b8279", "#b3aba1", "#3f3732", "#857c72", "#c9c3b9", "#b9b2a7"];
  const [SKIN, HAIR, HAIR_DARK, GREY, ASH, BEARD_DARK, BEARD_MID, BEARD, BEARD_SHADE] = HEAD_PALETTE.map((_, i) => i);
  BL.characters.add({
    handle: "Bitcoin-Bill",
    github: "Bitclank-Bill",
    display: "Bitclank-Bill",
    joined: 1792943472,
    lastCommit: 1792943472,
    look: {
      face: "beard", noPupils: true, height: 1.04, petRidesHat: true,
      skin: "#d99a74", hair: "#3b3430", fur: "#a97f52",
      portrait: { min: [-1, -2, 0], max: [7, 6, 8] }
    },
    voice: {
      poke: "clank clank",
      idle: [
        "Roll the dice, make the seed.",
        "Not your keys, not your coconuts.",
        "Read the white paper. Then read it again.",
        "Laser eyes on. Stack sats.",
        "Hold on tight, little dog.",
        "Proof of work, not proof of talk."
      ]
    },
    dress: {
      torso(k, v) {
        const skin = k.skinJ, cord = k.color("#2a2018"), coin = k.color("#f7931a");
        v.fill(1, 7, 3, 7, 1, 4, k.color(CARIBBEAN));
        v.fill(1, 1, 7, 7, 1, 4, skin);
        v.fill(7, 7, 7, 7, 1, 4, skin);
        v.fill(3, 5, 6, 7, 4, 4, skin);
        v.set(4, 5, 4, skin);
        v.set(3, 6, 4, cord); v.set(5, 6, 4, cord); v.set(4, 5, 4, cord);
        v.set(4, 4, 4, coin);
      },
      club(k) {
        const v = guitarVox(), unit = k.u / 2, origin = { x: -0.5 * unit, y: 0, z: 0 };
        return {
          default: voxelGeometry(v, { unit, palette: GUITAR_PALETTE, origin }),
          rest: { x: 0.95, z: 0 }, carry: { x: 0.95, z: 0 }
        };
      },
      model(k, wear) {
        const H = BL.heroBody, u = k.u, F = H.FRONT, v = makeVox(), z = 3.001;
        const lock = (x, y, z, a, b) => v.set(x, y, z, speckle(x, y, z) < 16 ? b : a);
        v.fill(0, 6, 0, 5, 0, 5, SKIN);
        v.fill(1, 5, 0, 1, 6, 6, SKIN);
        for (let x = -1; x <= 7; x++) for (let z = -1; z <= 6; z++) for (let y = 6; y <= 8; y++) if (y < 8 || x > -1 && x < 7 && z > -1 && z < 6) lock(x, y, z, HAIR, HAIR_DARK);
        for (let x = -1; x <= 7; x++) for (let z = -2; z <= -1; z++) for (let y = -2; y <= 5; y++) if (z > -2 || x > -1 && x < 7) lock(x, y, z, HAIR, HAIR_DARK);
        for (const x of [-1, 7]) for (let z = 0; z <= 4; z++) for (let y = 2; y <= 5; y++) v.set(x, y, z, z < 3 ? HAIR : y === 2 + (z & 1) ? ASH : GREY);
        for (let x = 0; x <= 6; x++) for (let y = 0; y <= 1; y++) for (let z = 5; z <= 7; z++) if (y || z < 7 || x % 6) lock(x, y, z, y ? BEARD_DARK : x % 6 ? BEARD : BEARD_MID, y ? BEARD_DARK : BEARD_SHADE);
        for (let x = 1; x <= 5; x++) for (let y = -2; y <= -1; y++) for (let z = 5; z <= 7; z++) if (y > -2 || z < 7 && x > 1 && x < 5) lock(x, y, z, BEARD, BEARD_SHADE);
        const blocks = voxelGeometry(v, { unit: u, palette: HEAD_PALETTE, origin: { x: -3.5 * u, y: 0, z: -3 * u } });
        const face = (shut) => {
          const g = BL.models.geometry();
          for (const side of [-1, 1]) {
            const X = (a, b) => [Math.min(a * side, b * side), Math.max(a * side, b * side)];
            const [bx0, bx1] = X(0, 3.55), [ex0, ex1] = X(1.5, 3.5), [cx0, cx1] = X(1.62, 2.5);
            H.slab(g, H.rect(bx0, bx1, 4, 5.05, z, 0.18, 0.07 * side), F, 1, 0.9, HEAD_PALETTE[HAIR], HEAD_PALETTE[HAIR_DARK]);
            if (shut) {
              H.slab(g, H.rect(ex0, ex1, 2, 4, z), F, 0.1, 1, "#c38a68");
              H.slab(g, H.rect(ex0, ex1, 2.55, 2.75, z + 0.1), F, 0.03, 1, "#62453a");
            } else {
              H.slab(g, H.rect(ex0, ex1, 2, 4, z, 0.12), F, 0.06, 1, ORANGE, ORANGE, 1);
              H.slab(g, H.rect(cx0, cx1, 3, 3.88, z + 0.06, 0.1), F, 0.03, 1, ORANGE_CORE, ORANGE_CORE, 1.4);
            }
            H.slab(g, H.rect(2 * side - 0.36, 2 * side + 0.36, 0.12, 0.88, 5.001, 0.1), F, 0.14, 0.8, "#f2efe4", "#d6d0c0");
          }
          H.noseBlock(g, H.rect(-1.5, 1.5, 2, 4, z, 0.4), F, 1.9, "#f0ab80", "#cc9170");
          return g;
        };
        const head = (shut) => BL.models.merge(blocks, H.scaled(face(shut), u));
        return { ...wear(), headOpen: head(false), headClosed: head(true) };
      },
      hatNodes(k) {
        addChild(k.parts.head, createNode({ geometry: voxelGeometry(hatVox(), { unit: k.u / 2, palette: HAT_PALETTE, origin: { x: -3.5 * k.u, y: 0, z: -3 * k.u } }) }));
      },
      refine(k, part, v) {
        if (part !== "torso") return;
        const blue = k.color(CARIBBEAN), deep = k.color("#1a9fc0"), green = k.color("#6fd3ae"), yellow = k.color("#d6e89a"), cells = [];
        v.each((x, y, z, c) => { if (c === blue) cells.push(x, y, z); });
        for (let i = 0; i < cells.length; i += 3) {
          const x = cells[i], y = cells[i + 1], z = cells[i + 2];
          const fade = Math.sin(x * 0.21 + y * 0.12) + Math.sin(y * 0.26 - x * 0.07 + z * 0.1 + 1.3) + (speckle(x, y, z) / 100 - 0.5) * 0.7;
          if (fade > 1.35) v.set(x, y, z, yellow);
          else if (fade > 0.75) v.set(x, y, z, green);
          else if (fade < -1.2) v.set(x, y, z, deep);
        }
      },
      extras(k) {
        const s = 0.7, h = k.h, unit = k.u / 2;
        k.parts.dog = createNode({
          position: { x: 0.55 * h, y: -k.legH, z: -0.25 * h }, scale: { x: s, y: s, z: s },
          geometry: voxelGeometry(kobeVox(), { unit: unit / 2, palette: KOBE_PALETTE, origin: { x: -0.5 * unit, y: 0, z: -0.5 * unit }, emissive: KOBE_GLOW })
        });
        addChild(k.root, k.parts.dog);
        addChild(k.parts.torso, createNode({ position: { x: 0, y: 1.3 * k.u, z: 0 }, geometry: voxelGeometry(sashVox(), { unit: unit / 2, palette: SASH_PALETTE, origin: { x: -0.25 * unit, y: 0, z: 0 } }) }));
      }
    }
  });
})();

sources.Global-DSB:
(() => {
  "use strict";
  const BL = window.BL;

  BL.characters.add({
    handle: "Global-DSB",
    joined: 1761945600,
    lastCommit: 1761945600,

    look: {
      bald: true,
      hairless: true,
      cleanShaven: true,
      noBrow: true,
      noPupils: true,
      face: "none",
      height: 1.10,
      skin: "#3a1a12",
      hair: "#1a0a08",
      fur: "#2a120c",
      eyeColor: "#ff2200",
      eyeGlow: 0.85
    },

    voice: {
      poke: "Global nonsense incoming.",
      idle: [
        "Hotter than the chain.",
        "Spikes up.",
        "Bitcoin or burn.",
        "No mercy, only magma.",
        "Skull stays lit.",
        "DSB does not cool down."
      ]
    },

    dress: {
      skull(k, v) {
        const rock   = k.color("#3a1a12");
        const rockLt = k.color("#5c2a18");
        const lava   = k.color("#ff3a00");
        const lavaHi = k.color("#ffaa22");
        const black  = k.color("#0a0504");

        v.fill(0, 6, 0, 6, 0, 5, rock);
        v.fill(1, 1, 2, 5, 3, 3, lava);
        v.fill(5, 5, 2, 5, 3, 3, lava);
        v.fill(2, 4, 1, 1, 4, 4, lavaHi);
        v.fill(1, 2, 3, 4, 5, 5, black);
        v.fill(4, 5, 3, 4, 5, 5, black);
        return true;
      },

      eyes(k, v) {
        const glow = k.color("#ff2200");
        const core = k.color("#ffee44");
        for (const x of [1, 5]) {
          v.set(x, 3, 5, glow);
          v.set(x, 3, 6, core);
          k.eyeCells.push([x, 3]);
        }
        k.headEmissive = { [glow]: 0.9, [core]: 1 };
        return true;
      },

      hat(k, v) {
        const helm   = k.color("#0d0d10");
        const helmLt = k.color("#2a2a30");
        const spike  = k.color("#111114");
        const btc    = k.color("#f7931a");
        const heart  = k.color("#ff2244");
        const bone   = k.color("#e8e0d0");

        v.fill(-1, 7, 5, 8, -1, 6, helm);
        v.fill(0, 6, 8, 9, 0, 5, helmLt);

        for (const x of [0, 2, 4, 6]) {
          v.set(x, 10, 2, spike);
          v.set(x, 11, 2, spike);
        }
        v.set(1, 10, 3, spike);
        v.set(5, 10, 3, spike);

        v.fill(2, 4, 6, 7, 6, 6, btc);
        v.set(3, 5, 6, btc);
        v.set(3, 8, 6, btc);

        v.set(1, 6, 6, heart);
        v.set(5, 6, 6, heart);
        v.set(2, 5, 6, heart);
        v.set(4, 5, 6, heart);

        v.set(0, 6, 5, bone);
        v.set(6, 6, 5, bone);
      },

      torso(k, v) {
        const rock   = k.color("#2a120c");
        const rockLt = k.color("#4a2218");
        const lava   = k.color("#ff3a00");
        const lavaHi = k.color("#ff8800");

        v.fill(0, 8, 0, 7, 0, 5, k.jit(rock, rockLt, 0.3));
        v.fill(2, 2, 1, 6, 5, 5, lava);
        v.fill(6, 6, 2, 5, 5, 5, lavaHi);
        v.set(4, 4, 5, lava);
        v.set(3, 6, 5, lavaHi);
      }
    }
  });
})();

