(() => {
  "use strict";
  const BL = window.BL;
  const { box, lathe, merge, turnedZ } = BL.models;
  const { createNode, addChild } = BL.scene;
  const skateboardGeometry = (h) => merge(
    box({ w: 0.22 * h, h: 0.8 * h, d: 0.03 * h, color: "#7cc242" }),
    box({ w: 0.2 * h, h: 0.08 * h, d: 0.03 * h, color: "#f7931a", offset: { z: -0.006 * h } }),
    ...[-0.28, 0.28].map((y) => box({ w: 0.2 * h, h: 0.03 * h, d: 0.045 * h, color: "#8a8a8a", offset: { y: y * h, z: -0.03 * h } })),
    ...[-0.28, 0.28].flatMap((y) => [-0.085, 0.085].map((x) => box({ w: 0.06 * h, h: 0.06 * h, d: 0.05 * h, color: "#1a1a1a", offset: { x: x * h, y: y * h, z: -0.07 * h } })))
  );
  const DECK = { y: [-0.4, -0.386, -0.355, -0.3, -0.21, -0.05, 0.05, 0.21, 0.3, 0.355, 0.386, 0.4], wide: [0.03, 0.068, 0.098, 0.11, 0.11, 0.11, 0.11, 0.11, 0.11, 0.098, 0.068, 0.03],
    kick: [0.05, 0.044, 0.03, 0.01, 0, 0, 0, 0, 0.01, 0.03, 0.044, 0.05] };
  const TRUCK = 0.27, AXLE = -0.045, WHEEL = 0.022, TRACK = 0.095;
  const deckGeometry = (h) => {
    const H = BL.heroBody, geo = BL.models.geometry(), ply = (thick, lift, trim) => DECK.y.map((y, i) => [y, DECK.wide[i] - trim, thick, 0.0006, 0, DECK.kick[i] + lift]);
    H.loft(geo, ply(0.006, 0, 0), "#c9a66b");
    H.loft(geo, ply(0.0012, 0.0072, 0.003), "#1b1b1d");
    H.loft(geo, ply(0.0012, -0.0072, 0.003), DECK.y.slice(1).map((_, i) => i === 5 ? "#f7931a" : i === 4 || i === 6 ? "#6faa2f" : "#7cc242"));
    return merge(H.scaled(geo, h), ...[-TRUCK, TRUCK].flatMap((y) => [
      box({ w: 0.07 * h, h: 0.075 * h, d: 0.006 * h, color: "#8d939a", offset: { y: y * h, z: -0.01 * h } }),
      box({ w: 0.032 * h, h: 0.032 * h, d: 0.02 * h, color: "#6d727a", offset: { y: (y - Math.sign(y) * 0.02) * h, z: -0.022 * h } }),
      box({ w: 0.12 * h, h: 0.026 * h, d: 0.02 * h, color: "#9aa0a8", offset: { y: y * h, z: -0.032 * h } }),
      box({ w: 0.2 * h, h: 0.008 * h, d: 0.008 * h, color: "#c3c8ce", offset: { y: y * h, z: AXLE * h } })
    ]));
  };
  const wheelGeometry = (h) => turnedZ(merge(
    lathe({ profile: [[0, -0.015 * h], [0.013 * h, -0.015 * h], [WHEEL * h, -0.011 * h], [WHEEL * h, 0.011 * h], [0.013 * h, 0.015 * h], [0, 0.015 * h]], segments: 10, color: "#f1ead6" }),
    lathe({ profile: [[0, -0.0165 * h], [0.008 * h, -0.0165 * h], [0.008 * h, 0.0165 * h], [0, 0.0165 * h]], segments: 6, color: "#f7931a" })
  ), Math.PI / 2);
  BL.characters.add({
    handle: "bc1gui",
    display: "ottoz0r",
    github: "ottoz0r",
    joined: 1788800918,
    lastCommit: 1788190400,
    look: { portrait: { min: [-3, -2, -1], max: [7, 13, 8] }, skater: true, hairless: true, noBrow: true, face: "smirk", skin: "#f2a33c", hair: "#e4561f", fur: "#8f4f17" },
    dress: {
      hat(k, v) {
        const knit = k.color("#8cc63f"), knitDk = k.color("#6faa2f"), pom = k.color("#a9d94c"), btc = k.color("#f7931a");
        const rib = (x, y, z) => (x + z) % 2 ? knitDk : knit;
        v.fill(-1, 7, 4, 8, -1, 6, rib);
        v.fill(-1, 5, 9, 9, 0, 5, rib);
        v.fill(-2, 3, 10, 10, 1, 4, rib);
        v.fill(-3, 0, 11, 12, 1, 3, k.jit(pom, knit, 0.2));
        v.fill(-2, -1, 13, 13, 2, 2, pom);
        for (const [bx, by] of [[3, 8], [4, 8], [3, 7], [5, 7], [3, 6], [4, 6], [3, 5], [5, 5], [3, 4], [4, 4]]) v.set(bx, by, 6, btc);
      },
      crown(k, v) {
        const P = k.P, lens = k.color("#3f9c96");
        if (BL.models.STYLE !== "R") {
          for (const z of [-1, 1, 3]) {
            v.fill(-1, -1, -2, 3, z, z, k.hairJ);
            v.fill(7, 7, -2, 3, z, z, k.hairJ);
          }
          for (const x of [0, 2, 4, 6]) v.fill(x, x, -3, 3, -1, -1, k.hairJ);
        }
        v.fill(0, 6, 3, 3, 6, 6, P.black);
        v.fill(0, 1, 2, 3, 6, 6, lens);
        v.fill(5, 6, 2, 3, 6, 6, lens);
        v.fill(-1, -1, 3, 3, 4, 6, P.black);
        v.fill(7, 7, 3, 3, 4, 6, P.black);
      },
      extras(k) {
        const h = k.h;
        if (BL.models.STYLE !== "R") {
          k.parts.board = createNode({ position: { x: 0, y: 0.28 * h, z: -0.35 * h }, rotation: { x: 0, y: 0, z: 0.4 }, geometry: skateboardGeometry(h) });
          addChild(k.root, k.parts.board);
          return;
        }
        const rest = { x: 0, y: 0.28 * h, z: -0.215 * h, turn: 0.4 }, wheel = wheelGeometry(h);
        k.parts.board = createNode({ position: { x: rest.x, y: rest.y, z: rest.z }, rotation: { x: 0, y: 0, z: rest.turn }, geometry: deckGeometry(h) });
        k.parts.board.ride = { rest, under: (WHEEL - AXLE) * h, deck: (WHEEL - AXLE + 0.0085) * h, wheel: WHEEL * h };
        k.parts.boardWheels = [-TRUCK, TRUCK].flatMap((y) => [-TRACK, TRACK].map((x) => createNode({ position: { x: x * h, y: y * h, z: AXLE * h }, geometry: wheel })));
        for (const node of k.parts.boardWheels) addChild(k.parts.board, node);
        addChild(k.root, k.parts.board);
        const H = BL.heroBody, geo = BL.models.geometry(), hair = "#e4561f", dark = "#c94a18";
        [-3, -1, 1, 3].forEach((x, i) => H.loft(geo, [[4.2, 0.5, 0.17, 0.05, x, -3.17], [0, 0.5, 0.17, 0.05, x, -3.17], [i % 2 ? -2.3 : -3, 0.44, 0.15, 0.05, x, -2.55]], i % 2 ? dark : hair));
        for (const side of [-1, 1]) [-2.4, -0.5, 1.4].forEach((z, i) => H.loft(geo, [[4.2, 0.17, 0.5, 0.05, side * 3.67, z], [0.4, 0.17, 0.5, 0.05, side * 3.67, z], [i === 1 ? -2 : -1.4, 0.15, 0.44, 0.05, side * 3.2, z]], i % 2 ? hair : dark));
        addChild(k.parts.head, createNode({ geometry: H.scaled(geo, k.u) }));
      }
    }
  });
})();

sources.hotpixelgroup:
(() => {
  "use strict";
  const BL = window.BL;
  const { makeVox, voxelGeometry, bevelBox, merge } = BL.models;
  const { createNode, addChild } = BL.scene;
  const { hexToRgb } = BL.math;
  const GREEN = "#1bcd6e", DARK = "#080a0e", CHARCOAL = "#161b28";
  const CLUB_PALETTE = ["#38291f", "#594231", "#947657"].map(hexToRgb);

  const diamondFist = (u) => {
    const pieces = [];
    const gem = (x, y, z, w, h, d, color) => {
      const geo = bevelBox({
        w: w * u, h: h * u, d: d * u, bevel: Math.min(w, h, d) * u * 0.28,
        color, emissive: 0.15, offset: { x: x * u, y: y * u, z: z * u }
      });
      const facets = [];
      for (const face of geo.faces) {
        if (face.i.length !== 4) { facets.push(face); continue; }
        const [a, b, c, d] = face.i;
        facets.push({ i: [a, b, c], color: face.color, emissive: face.emissive });
        facets.push({ i: [a, c, d], color: hexToRgb("#b9edff"), emissive: 0.15 });
      }
      geo.faces = facets;
      pieces.push(geo);
    };
    gem(0, 10.6, 0, 2.8, 2.6, 2.8, "#88dfff");
    gem(0, 13, 0, 5.8, 4.2, 3.8, "#e8eaf0");
    for (let i = 0; i < 4; i++) {
      const x = -2.1 + i * 1.4, y = i === 0 || i === 3 ? 14.8 : 15.2;
      gem(x, y, 1, 1.35, 2.4, 2.6, i % 2 ? "#d7f6ff" : "#a4e6ff");
      gem(x, y - 1.5, 2, 1.3, 1.4, 1.7, "#e8eaf0");
    }
    gem(2.5, 12.5, 1.1, 2, 2.6, 2.6, "#00c2ff");
    gem(1.5, 12.5, 2.3, 2.5, 1.6, 1.8, "#d7f6ff");
    return merge(...pieces);
  };

  const LOGO = [
    "000000000000000000000000",
    "000000000000000000000000",
    "000000000001000000000000",
    "000000000001100000000000",
    "000000000011100000000000",
    "000000000001110000000000",
    "000000000001111000000000",
    "000000000000111000000000",
    "000000001000110000000000",
    "000000001000010000000000",
    "000000001100000000000000",
    "000000001100000000100000",
    "000000001100000001100000",
    "000000011110000011000000",
    "000000011110000111000011",
    "000000111110001111000011",
    "000000111110001111000111",
    "001001111110011111000111",
    "011011111110011111000110",
    "011111111110011111100100",
    "011111111110000011100000",
    "011111111110000001110000",
    "011111111100000000110000",
    "011111111000000000011000",
    "111111111000000000001000",
    "111111110000000000101100",
    "111111100000000000111100",
    "111111000000000000111100",
    "111111000000000001111110",
    "111110000000000001111110",
    "111110000000000111111100",
    "111110000000000111111100",
    "011110000000000111111100",
    "011110000000000111111100",
    "001110000000000111111000",
    "001111000000101111111000",
    "000111110011111111110000",
    "000011111111111111100000",
    "000000111111111110000000",
    "000000001111111000000000"
  ];

  BL.characters.add({
    handle: "hotpixelgroup",
    joined: 1790600000,
    lastCommit: 1790680000,
    display: "hotpixelgroup",
    github: "hotpixelgroup",
    look: {
      skin: "#c48253",
      hair: DARK,
      fur: CHARCOAL,
      height: 1.08,
      eyeColor: "#e8eaf0",
      face: "beard",
      portrait: { min: [-2, -2, -1], max: [8, 18, 8] }
    },
    voice: {
      poke: "Hot pixels, forged blocks.",
      idle: [
        "Proof of work never sleeps.",
        "The hardest stone yields to patience.",
        "Tick tock, next block.",
        "Stacking sats, pixel by pixel."
      ]
    },
    dress: {
      torso(k, v) {
        const dark = k.color(DARK), charcoal = k.color(CHARCOAL);
        const green = k.color(GREEN), shade = k.color("#13a356");
        const bone = k.color("#e8e5d5"), leather = k.color("#38291f");
        k.loin = [charcoal, dark];
        v.fill(1, 7, 3, 7, 1, 4, k.skinJ);
        v.fill(0, 8, 0, 2, 0, 5, (x, y, z) => (x + z) % 4 === 0 ? dark : charcoal);
        v.fill(0, 8, 3, 3, 0, 5, leather);
        for (let x = 6; x <= 9; x++) for (let z = 0; z <= 5; z++) {
          const hem = 5 + (x + z) % 2;
          v.fill(x, x, hem, 8, z, z, (a, y) => (a + y + z) % 5 === 0 ? shade : green);
        }
        const badge = makeVox();
        badge.fill(0, 35, 0, 43, 0, 1, bone);
        badge.fill(2, 33, 2, 41, 2, 2, green);
        for (let row = 0; row < LOGO.length; row++) for (let x = 0; x < 24; x++) {
          if (LOGO[row][x] === "1") badge.set(x + 6, 41 - row, 3, dark);
        }
        addChild(k.root, createNode({
          position: { x: 0, y: 2.7 * k.u, z: 3.5 * k.u },
          geometry: k.vg(badge, { x: -18 * k.u, y: -22 * k.u, z: 0 }),
          scale: { x: 0.125, y: 0.125, z: 0.125 }
        }));
      },
      club(k) {
        const v = makeVox(), u = k.u;
        v.fill(0, 0, -2, 10, 0, 0, 0);
        for (const y of [0, 4, 9]) {
          v.fill(-1, 1, y, y, -1, 1, 2);
          v.set(0, y + 1, 0, 1);
        }
        const handle = voxelGeometry(v, {
          unit: u, palette: CLUB_PALETTE, origin: { x: -u, y: -u, z: -u }
        });
        const geo = merge(handle, diamondFist(u));
        return { voxels: v, default: geo,
          rest: { x: 0.2, z: -0.05 }, carry: { x: 0.35, z: 0 } };
      },
      hat(k, v) {
        v.fill(-1, 7, 6, 7, -1, 6, k.color(CHARCOAL));
      },
      hatNodes(k) {
        const dark = k.color(CHARCOAL);
        const green = k.color(GREEN), light = k.color("#2ee085"), shade = k.color("#13a356");
        const outline = [
          "000000100", "000001100", "000011100", "000111000",
          "001111000", "001111100", "011111110", "011111110",
          "111111111", "111111111", "011111110", "001111100"
        ];
        const tongues = [[-6, 0, 0.7], [3, 4, 1], [12, 0, 0.7]];
        for (const [x0, y0, size] of tongues) {
          const v = makeVox();
          for (let row = 0; row < outline.length; row++) for (let x = 0; x < 9; x++) {
            if (outline[row][x] !== "1") continue;
            const y = y0 + outline.length - 1 - row;
            const inset = x > 0 && x < 8 && outline[row][x - 1] === "1"
              && outline[row][x + 1] === "1" && row < outline.length - 1;
            v.fill(x0 + x, x0 + x, y, y, 0, 3, inset ? shade : dark);
            if (inset) {
              v.set(x0 + x, y, 4, x < 4 ? light : green);
              v.set(x0 + x, y, -1, green);
            }
          }
          addChild(k.parts.head, createNode({
            position: { x: (x0 + 4.5 - 7) * 0.5 * k.u, y: (8 + y0 * 0.5) * k.u, z: 0 },
            geometry: k.vg(v, { x: -(x0 + 4.5) * k.u, y: -y0 * k.u, z: 0 }),
            scale: { x: 0.5 * size, y: 0.5 * size, z: 0.5 * size }
          }));
        }
      },
      mark(k, v) {
        const green = k.color(GREEN);
        for (const x of [0, 1, 5, 6]) v.set(x, 1, 7, green);
      },
      gear(k) {
        if (BL.models.STYLE !== "R") return;
        const H = BL.heroBody, band = BL.models.geometry();
        H.loft(band, [[0.5, 1.7, 1.76, 0.52], [0.36, 1.78, 1.84, 0.55], [-0.36, 1.72, 1.78, 0.53], [-0.5, 1.6, 1.66, 0.5]], ["#d6d2c0", "#e8e5d5", "#d6d2c0"]);
        const geometry = H.scaled(band, k.u);
        for (const arm of [k.parts.armR, k.parts.armL]) { const worn = createNode({ geometry }); worn.forearm = 0.84; addChild(arm, worn); }
      },
      refine(k, part, v) {
        if (part !== "arm") return;
        const bone = k.color("#e8e5d5"), band = [];
        const f = k.fine;
        for (let y = 3 * f; y < 5 * f; y++) for (let x = -2 * f; x <= 5 * f; x++) for (let z = -2 * f; z <= 5 * f; z++) {
          if (v.has(x, y, z)) continue;
          if (v.has(x + 1, y, z) || v.has(x - 1, y, z) || v.has(x, y, z + 1) || v.has(x, y, z - 1)) band.push(x, y, z);
        }
        for (let i = 0; i < band.length; i += 3) v.set(band[i], band[i + 1], band[i + 2], bone);
      }
    }
  });
})();

sources.itsLiran:
(() => {
  "use strict";
  const BL = window.BL;
  const { makeVox } = BL.models;
  const { createNode, addChild, removeChild } = BL.scene;
  const GLYPH = {
    T: ["111", "010", "010", "010", "010"],
    A: ["010", "101", "111", "101", "101"],
    P: ["110", "101", "110", "100", "100"],
    R: ["110", "101", "110", "101", "101"],
    O: ["111", "101", "101", "101", "111"],
    B: ["110", "101", "110", "101", "110"],
    L: ["100", "100", "100", "100", "111"],
    "=": ["000", "111", "000", "111", "000"],
    "1": ["010", "110", "010", "010", "111"]
  };
  const BITCOIN = "#f7931a";
  const hash = (x, y, z) => (Math.imul(x + 11, 73856093) ^ Math.imul(y + 17, 19349663) ^ Math.imul(z + 29, 83492791)) >>> 0;
  const stamp = (v, word, put) => {
    let pen = 0;
    for (const ch of word) {
      const g = GLYPH[ch];
      for (let r = 0; r < 5; r++) for (let c = 0; c < 3; c++) if (g[r][c] === "1") put(pen + c, r);
      pen += 4;
    }
  };
  const plateCells = (w, h, put) => {
    for (let a = 0; a < w; a++) for (let b = 0; b < h; b++) {
      if ((a === 0 || a === w - 1) && (b === 0 || b === h - 1)) continue;
      put(a, b);
    }
  };
  BL.characters.add({
    handle: "itsLiran",
    github: "LiranCohen",
    display: "Liran",
    joined: 1792641623,
    lastCommit: 1792641623,
    look: {
      bald: true,
      face: "beard",
      skin: "#d9a06b",
      hair: "#3d2a1a",
      eyeColor: "#6e4a26",
      noPupils: true,
      height: 1.04,
      portrait: { min: [-1, -2, -1], max: [7, 9, 11] }
    },
    voice: {
      poke: "Hey! Watch the beard.",
      idle: ["Nice weather for bananas.", "Ooga.", "Just strolling through.", "Someone left the pile full again."]
    },
    dress: {
      hat(k, v) {
        const cream = k.color("#ded4b8"), sand = k.color("#c9bb98"), khaki = k.color("#ab9d74");
        const olive = k.color("#8a7f5c"), brown = k.color("#6a5f44"), dark = k.color("#4a4234");
        const tones = [cream, sand, khaki, olive, brown, dark];
        const slots = [0, 1, 2, 1, 0, 3, 2, 1, 4, 0, 2, 3, 5, 1, 2, 4];
        const camo = (x, y, z) => {
          const coarse = hash(x >> 1, y >> 1, z >> 1), fine = hash(x, y, z);
          return tones[slots[(fine % 7 === 0 ? fine : coarse) % slots.length]];
        };
        v.fill(-1, 7, 5, 7, -1, 6, camo);
        v.fill(0, 6, 8, 8, 0, 5, camo);
        v.fill(3, 4, 9, 9, 2, 3, khaki);
        const under = k.color("#2e261c");
        v.fill(1, 5, 5, 5, -1, -1, k.color("#55493a"));
        for (const [z, x0, x1] of [[7, -1, 7], [8, -1, 7], [9, 0, 6], [10, 0, 6], [11, 1, 5]]) {
          v.fill(x0, x1, 5, 5, z, z, camo);
          v.fill(x0, x1, 4, 4, z, z, under);
        }
      },
      club(k) {
        const rod = (body, chrome, grip, energy, energyHi) => {
          const v = makeVox();
          v.fill(0, 1, 0, 2, 0, 1, grip);
          v.fill(-1, 2, 3, 3, -1, 2, chrome);
          v.fill(0, 1, 4, 8, 0, 1, body);
          v.fill(-1, 2, 4, 4, -1, 2, energy);
          v.fill(-1, 2, 6, 6, -1, 2, energy);
          v.fill(-1, 2, 8, 8, -1, 2, energy);
          v.fill(-1, 2, 9, 9, -1, 2, chrome);
          v.fill(0, 1, 10, 10, 0, 1, energyHi);
          v.set(-1, 10, 0, energy); v.set(2, 10, 1, energy);
          return k.vg(v, { x: -1 * k.u, y: -1 * k.u, z: -1 * k.u }, { [energy]: 0.85, [energyHi]: 1 });
        };
        const standard = rod(k.color("#2b2e36"), k.color("#9aa1aa"), k.color("#141518"), k.color("#ff8c1a"), k.color("#ffd27a"));
        return { default: standard, rest: { x: 0.24, z: 0 }, carry: { x: 0.95, z: 0 } };
      },
      gear(k) {
        const shirt = k.color("#141519"), shirtHi = k.color("#1b1d22");
        const denim = k.color("#2c3e63"), denimDk = k.color("#22304d");
        const belt = k.color("#111214"), buckle = k.color("#8f969e"), strap = k.color("#43464d");
        const sole = k.color("#d9d3c5"), shoe = k.color("#191a1d");
        const denimAt = (x, y, z) => (hash(x, y, z) % 7 === 0 ? denimDk : denim);
        const shirtAt = (x, y, z) => (hash(x, y, z) % 11 === 0 ? shirtHi : shirt);
        const jeanLeg = (side) => {
          const v = makeVox();
          v.fill(0, 3, 2, 4, 0, 3, denimAt);
          v.fill(0, 3, 0, 0, 0, 5, sole);
          v.set(side < 0 ? 3 : 0, 0, 6, sole);
          v.set(side < 0 ? 1 : 2, 0, 6, sole);
          v.fill(0, 3, 1, 1, 0, 5, shoe);
          return k.vg(v, { x: -2 * k.u, y: -5 * k.u, z: -2.5 * k.u });
        };
        k.parts.legR.geometry = jeanLeg(-1);
        k.parts.legL.geometry = jeanLeg(1);
        const torso = makeVox();
        torso.fill(0, 8, 0, 2, 0, 5, denimAt);
        torso.fill(0, 8, 2, 2, 0, 5, belt);
        torso.set(4, 2, 5, buckle);
        torso.fill(1, 7, 3, 7, 1, 4, shirtAt);
        for (let y = 4; y <= 7; y++) {
          const x = 7 - Math.round((y - 4) * 1.6);
          for (const z of [1, 4]) for (const dx of [0, 1]) if (x + dx >= 1 && x + dx <= 7) torso.set(x + dx, y, z, strap);
        }
        torso.set(7, 4, 4, buckle);
        k.parts.torso.geometry = k.vg(torso, { x: -4.5 * k.u, y: 0, z: -3 * k.u });
        const arm = makeVox();
        arm.fill(0, 2, 2, 7, 0, 2, k.skinJ);
        arm.fill(-1, 3, 8, 10, -1, 3, shirt);
        arm.fill(-1, 3, 0, 1, -1, 3, k.skinJ);
        const armGeo = k.vg(arm, { x: -1.5 * k.u, y: -11 * k.u, z: -1.5 * k.u });
        k.parts.armR.geometry = armGeo;
        k.parts.armL.geometry = armGeo;
        k.parts.gunBody.visible = false;
        for (const round of k.parts.gunBananas) if (round.parent === k.parts.gun) removeChild(k.parts.gun, round);
        k.parts.gunBananas.length = 0;
        const caseC = k.color("#c9c2b0"), keyC = k.color("#ece6d7");
        const esc = k.color("#e8d46a"), tab = k.color("#8fa8d8"), caps = k.color("#e69a52");
        const shift = k.color("#9dbf9a"), enter = k.color("#a49ac8"), back = k.color("#4a4d55");
        const red = k.color("#b9695f");
        const keys = makeVox();
        keys.fill(-1, 0, -1, 14, 0, 45, caseC);
        const placeRow = (y0, spec, x, flip) => {
          const total = spec.reduce((n, [w]) => n + w, 0) + spec.length - 1;
          let col = 1 + Math.floor((44 - total) / 2);
          for (const [w, color] of spec) {
            const z0 = flip ? col : 45 - (col + w - 1);
            const z1 = flip ? col + w - 1 : 45 - col;
            keys.fill(x, x, y0, y0 + 1, z0, z1, color);
            col += w + 1;
          }
        };
        const cream = (count) => Array.from({ length: count }, () => [2, keyC]);
        const ROWS = [
          [12, [[2, esc], ...cream(12), [5, back]]],
          [9, [[3, tab], ...cream(12), [4, shift]]],
          [6, [[4, caps], ...cream(11), [6, enter]]],
          [3, [[5, shift], ...cream(10), [5, caps], [2, red]]],
          [0, [[3, caps], [3, shift], [12, keyC], [3, tab], [3, caps]]]
        ];
        for (const [y0, spec] of ROWS) {
          placeRow(y0, spec, 1, false);
          placeRow(y0, spec, -2, true);
        }
        const belly = k.traits.belly;
        const headRear = 0.02 * k.h - 4 * k.u;
        const gunZ = Math.min(-0.245 * k.h, headRear - 0.055 * k.h);
        const BOARD_SCALE = 0.2;
        const halfThickness = 2 * k.u * BOARD_SCALE;
        const torsoBack = -3 * k.u * belly;
        const gap = torsoBack - (gunZ + halfThickness);
        const boardShift = Math.max(0, gap + 0.005);
        addChild(k.parts.gun, createNode({
          geometry: k.vg(keys, { x: 0, y: -7 * k.u, z: -23 * k.u }),
          position: { x: -boardShift, y: 0, z: 0 },
          scale: { x: BOARD_SCALE, y: BOARD_SCALE, z: BOARD_SCALE }
        }));
      },
      hatNodes(k) {
        const v = makeVox(), ink = k.color("#4e3520");
        stamp(v, "TAPROOT", (x, r) => v.set(x, 4 - r, 0, ink));
        addChild(k.parts.head, createNode({
          position: { x: 0, y: 6.8 * k.u, z: 4.05 * k.u },
          geometry: k.vg(v, { x: -13.5 * k.u, y: -2.5 * k.u, z: 0 }),
          scale: { x: 0.25, y: 0.25, z: 0.25 }
        }));
        const plate = makeVox();
        const btc = k.color(BITCOIN), btcHi = k.color("#fff1d0");
        plateCells(5, 7, (z, y) => plate.set(0, y, z, btc));
        stamp(plate, "B", (x, r) => plate.set(0, 5 - r, 3 - x, btcHi));
        addChild(k.parts.head, createNode({
          position: { x: 4.45 * k.u, y: 6.5 * k.u, z: 0.5 * k.u },
          geometry: k.vg(plate, { x: 0, y: -3.5 * k.u, z: -2.5 * k.u }),
          scale: { x: 0.35, y: 0.35, z: 0.35 }
        }));
        const tag = k.color("#26241f"), tagIn = k.color("#d9d2c0"), tagHi = k.color("#f5efe0");
        const badge = makeVox();
        for (let y = 0; y <= 8; y++) for (let z = 0; z <= 22; z++) {
          if (((y === 0 || y === 8) && (z <= 1 || z >= 21)) || ((y === 1 || y === 7) && (z === 0 || z === 22))) continue;
          const rim = y === 0 || y === 8 || z === 0 || z === 22 || ((y === 1 || y === 7) && (z === 1 || z === 21));
          badge.set(0, y, z, rim ? tagIn : tag);
        }
        stamp(badge, "LOT=1", (x, r) => badge.set(0, 2 + (4 - r), 2 + x, tagHi));
        addChild(k.parts.head, createNode({
          position: { x: -4.45 * k.u, y: 6.5 * k.u, z: 0 },
          geometry: k.vg(badge, { x: -k.u, y: -4.5 * k.u, z: -11.5 * k.u }),
          scale: { x: 0.28, y: 0.28, z: 0.28 }
        }));
      },
      eyes(k, v) {
        const white = k.P.white, pupil = k.P.black;
        const iris = k.traits.eyeColor ? k.color(k.traits.eyeColor) : white;
        for (const [outer, inner] of [[0, 1], [6, 5]]) {
          v.set(outer, 2, 5, white); v.set(inner, 2, 5, white);
          v.set(outer, 3, 5, iris); v.set(inner, 3, 5, pupil);
          for (const x of [outer, inner]) for (const y of [2, 3]) k.eyeCells.push([x, y]);
        }
        return true;
      },
      extras(k) {
        const plate = makeVox();
        const plateC = k.color("#1a1c20"), btc = k.color(BITCOIN);
        plateCells(5, 7, (x, z) => plate.set(x, 0, z, plateC));
        stamp(plate, "B", (x, r) => plate.set(3 - x, 0, 1 + (4 - r), btc));
        addChild(k.parts.club, createNode({
          position: { x: 0, y: 10.01 * k.u, z: 0 },
          geometry: k.vg(plate, { x: -2.5 * k.u, y: 0, z: -3.5 * k.u }, { [btc]: 0.9 }),
          scale: { x: 0.25, y: 0.25, z: 0.25 }
        }));
      }
    }
  });
})();

sources.johnstackton21m:
(() => {
  "use strict";
  const BL = window.BL;
  const { box, ring, tube, merge, cached, geometry, pushVert, face, makeVox } = BL.models;
  const { hexToRgb } = BL.math;
  const { createNode, addChild } = BL.scene;
  const FUR = "#f1e9da", MUZZLE = "#faf5ec", NOSE = "#24201e", NOSTRIL = "#0a0909", SHINE = "#615a55", MOUTH = "#3b2320";
  const HELMET = "#c9a032", WORN = "#8f7a3a", GRIME = "#7f7b3f", LINING = "#6e6047";
  const VISOR = "#2a0d0a", GLARE = "#5c2a20", FRAME = "#161412", LASER = "#ff5a1f", HOT = "#ffb070";
  const SUIT = "#e0a020", SUIT_DK = "#a86a14", OLIVE = "#8c873c", GLYPH = "#dfe8f0";
  const METAL = "#3d4248", BOLT = "#9aa0a6", CABLE = "#1d1f22", GLOVE = "#4a4d52";
  const grit = (x, y, z) => ((Math.imul(x + 11, 73856093) ^ Math.imul(y + 7, 19349663) ^ Math.imul(z + 5, 83492791)) >>> 0) % 13;
  const shell = ({ r, cy, a0, a1, e0, e1, sa, se, paint, inside = false }) => {
    const geo = geometry(), rows = [], D = Math.PI / 180;
    for (let j = 0; j <= se; j++) {
      const e = (e0 + (e1 - e0) * j / se) * D, row = [];
      for (let i = 0; i <= sa; i++) {
        const a = (a0 + (a1 - a0) * i / sa) * D;
        row.push(pushVert(geo, r * Math.cos(e) * Math.sin(a), cy + r * Math.sin(e), r * Math.cos(e) * Math.cos(a)));
      }
      rows.push(row);
    }
    for (let j = 0; j < se; j++) for (let i = 0; i < sa; i++) {
      const c = paint(i, j);
      if (c === null) continue;
      const quad = [rows[j][i], rows[j][i + 1], rows[j + 1][i + 1], rows[j + 1][i]];
      face(geo, inside ? quad.reverse() : quad, hexToRgb(c));
    }
    return geo;
  };
  const R = 0.4, CY = 0.2;
  const helmetGeometry = cached(() => {
    const open = (i, j) => Math.abs(i - 12 + 0.5) < 3 && j < 3;
    const dome = (i, j) => open(i, j) ? null : j === 0 ? GRIME : grit(i, j, 0) < 2 ? WORN : grit(i, j, 1) < 1 ? GRIME : HELMET;
    return merge(
      shell({ r: R, cy: CY, a0: -180, a1: 180, e0: -15, e1: 90, sa: 24, se: 7, paint: dome }),
      shell({ r: R - 0.02, cy: CY, a0: -180, a1: 180, e0: -15, e1: 90, sa: 24, se: 7, paint: (i, j) => open(i, j) ? null : LINING, inside: true }),
      shell({ r: R + 0.006, cy: CY, a0: -62, a1: 62, e0: 30, e1: 62, sa: 8, se: 3, paint: () => FRAME }),
      shell({ r: R + 0.012, cy: CY, a0: -57, a1: 57, e0: 33, e1: 59, sa: 8, se: 3, paint: (i, j) => j === 1 && i > 1 && i < 4 ? GLARE : VISOR })
    );
  });
  const helmetFloorGeometry = cached(() => {
    const geo = geometry(), D = Math.PI / 180, y = CY + R * Math.sin(-15 * D), r = R * Math.cos(15 * D) - 0.004, ring = [];
    for (let i = 0; i < 24; i++) ring.push(pushVert(geo, r * Math.sin(-i / 24 * Math.PI * 2), y, r * Math.cos(-i / 24 * Math.PI * 2)));
    face(geo, ring, hexToRgb(LINING));
    return geo;
  });
  const PAD_Z = 0.03, DOME_Y = 0.05 + CY * Math.cos(0.55), DOME_Z = -0.1 - CY * Math.sin(0.55);
  const helmetPadGeometry = cached(() => {
    const geo = geometry(), r = Math.sqrt(R * R - (PAD_Z - DOME_Z) ** 2) - 0.004, ring = [];
    for (let i = 0; i < 24; i++) { const a = i / 24 * Math.PI * 2; ring.push(pushVert(geo, r * Math.cos(a), Math.max(0.01, DOME_Y + r * Math.sin(a)), PAD_Z)); }
    face(geo, ring, hexToRgb(LINING));
    return geo;
  });
  const neckRingGeometry = cached(() => {
    const bolts = [];
    for (let i = 0; i < 8; i++) {
      const a = (i + 0.5) / 8 * Math.PI * 2;
      bolts.push(box({ w: 0.028, h: 0.028, d: 0.028, color: BOLT, offset: { x: Math.sin(a) * 0.37, y: 0.5, z: Math.cos(a) * 0.37 } }));
    }
    const cable = tube({ rings: 10, segments: 6, radius: () => 0.014, colorFn: () => CABLE,
      path: (t) => ({ x: 0.36 - 0.12 * t, y: 0.48 - 0.1 * t + 0.06 * Math.sin(t * Math.PI), z: -0.3 * t }) });
    return merge(ring({ r: 0.35, thickness: 0.032, y: 0.5, segments: 16, color: METAL }), ring({ r: 0.33, thickness: 0.02, y: 0.45, segments: 16, color: CABLE }), ...bolts, cable);
  });
  const coinGeometry = cached(() => {
    const rows = [" # # ", "#### ", "#   #", "#### ", "#   #", "#### ", " # # "], c = 0.018, cells = [];
    rows.forEach((row, j) => [...row].forEach((ch, i) => {
      if (ch === "#") cells.push(box({ w: c, h: c, d: 0.008, color: GLYPH, offset: { x: (i - 2) * c, y: (3 - j) * c } }));
    }));
    return merge(...cells);
  });
  const packGeometry = cached(() => merge(
    box({ w: 0.3, h: 0.26, d: 0.1, color: METAL }),
    box({ w: 0.3, h: 0.035, d: 0.104, color: SUIT, offset: { y: 0.09 } }),
    box({ w: 0.05, h: 0.05, d: 0.02, color: BOLT, offset: { x: 0.08, y: -0.04, z: -0.055 } }),
    box({ w: 0.12, h: 0.02, d: 0.02, color: CABLE, offset: { x: -0.05, y: -0.06, z: -0.055 } })
  ));
  const suitJ = (x, y, z) => grit(x, y, z) < 1 ? OLIVE : SUIT;
  const armVox = (C) => {
    const v = makeVox();
    v.fill(0, 2, 3, 7, 0, 2, (x, y, z) => C[suitJ(x, y, z)]);
    v.fill(-1, 3, 8, 10, -1, 3, (x, y, z) => C[x === -1 || z === -1 ? SUIT_DK : SUIT]);
    v.fill(-1, 3, 2, 2, -1, 3, C[METAL]);
    v.fill(-1, 3, 0, 1, -1, 3, C[GLOVE]);
    return v;
  };
  const legVox = (C) => {
    const v = makeVox();
    v.fill(0, 3, 3, 4, 0, 3, (x, y, z) => C[suitJ(x, y, z)]);
    v.fill(0, 3, 2, 2, 0, 3, C[METAL]);
    v.fill(0, 3, 0, 1, 0, 5, C[GLOVE]);
    return v;
  };
  const colors = (k) => Object.fromEntries([SUIT, SUIT_DK, OLIVE, METAL, GLOVE].map((hex) => [hex, k.color(hex)]));
  BL.characters.add({
    handle: "johnstackton21m",
    display: "Doggo",
    joined: 1792114421,
    lastCommit: 1792114421,
    look: { skin: FUR, hair: FUR, fur: SUIT_DK, hairless: true, noBrow: true, noPupils: true, face: "none", noFlaps: true },
    voice: {
      poke: "GM. Wen Omega?",
      idle: ["GM. Wen Omega?", "I habs humgry", "Laser eyes til MacDomalts fries"]
    },
    dress: {
      torso(k, v) {
        const C = colors(k);
        v.fill(0, 8, 0, 7, 0, 5, (x, y, z) => C[y === 2 ? METAL : x === 0 || x === 8 || z === 0 ? SUIT_DK : z === 5 && grit(x, y, z) < 2 ? OLIVE : SUIT]);
        v.set(4, 2, 5, k.color(BOLT));
        k.loin = [C[SUIT_DK], C[OLIVE]];
      },
      gear(k) {
        const C = colors(k), u = k.u, h = k.h, glove = makeVox();
        k.parts.armR.geometry = k.parts.armL.geometry = k.vg(armVox(C), { x: -1.5 * u, y: -11 * u, z: -1.5 * u });
        k.parts.legR.geometry = k.parts.legL.geometry = k.vg(legVox(C), { x: -2 * u, y: -5 * u, z: -2.5 * u });
        glove.set(0, 1, 4, C[GLOVE]);
        glove.set(2, 1, 4, C[GLOVE]);
        k.parts.fingersR.geometry = k.parts.fingersL.geometry = k.vg(glove, { x: -1.5 * u, y: -u, z: -1.5 * u });
        addChild(k.root, createNode({ scale: { x: h, y: h, z: h }, geometry: neckRingGeometry() }));
        for (const x of [-0.14, 0.14]) addChild(k.parts.torso, createNode({ position: { x: x * h, y: 0.3 * h, z: 3.05 * u }, scale: { x: h, y: h, z: h }, geometry: coinGeometry() }));
      },
      skull(k, v) {
        const P = k.P, muzzle = k.color(MUZZLE), nose = k.color(NOSE), mouth = k.color(MOUTH);
        v.fill(0, 6, 0, 5, 0, 5, (x, y, z) => grit(x, y, z) < 1 ? P.skinDk : P.skin);
        v.fill(-1, 7, 0, 3, 1, 5, P.skin);
        for (const x of [0, 6]) for (const z of [0, 5]) v.del(x, 5, z);
        v.fill(0, 6, 4, 4, 6, 6, P.skinDk);
        v.fill(1, 5, 0, 2, 6, 8, muzzle);
        v.fill(2, 4, 3, 3, 6, 7, muzzle);
        v.fill(0, 6, -1, -1, 5, 8, (x) => x === 3 ? null : P.skin);
        for (const x of [0, 6]) v.fill(x, x, 0, 1, 6, 8, P.skin);
        v.fill(2, 4, 2, 3, 8, 9, nose);
        v.set(2, 2, 9, k.color(NOSTRIL));
        v.set(4, 2, 9, k.color(NOSTRIL));
        v.set(3, 3, 9, k.color(SHINE));
        v.fill(2, 4, 0, 0, 8, 8, mouth);
        return true;
      },
      eyes(k, v) {
        const laser = k.color(LASER), hot = k.color(HOT);
        for (const [x, c] of [[0, laser], [1, hot], [5, hot], [6, laser]]) {
          v.set(x, 3, 5, c);
          k.eyeCells.push([x, 3]);
        }
        k.headEmissive = { [laser]: 1, [hot]: 1 };
        k.lid = k.P.skinDk;
        return true;
      },
      hatNodes(k) {
        const h = k.h;
        addChild(k.parts.head, createNode({ position: { x: 0, y: 0.05 * h, z: -0.1 * h }, rotation: { x: -0.55, y: 0, z: 0 }, scale: { x: h, y: h, z: h }, geometry: helmetGeometry() }));
        if (BL.models.STYLE !== "R") return;
        addChild(k.parts.head, createNode({ position: { x: 0, y: 0.05 * h, z: -0.1 * h }, rotation: { x: -0.55, y: 0, z: 0 }, scale: { x: h, y: h, z: h }, geometry: helmetFloorGeometry() }));
        addChild(k.parts.head, createNode({ scale: { x: h, y: h, z: h }, geometry: helmetPadGeometry() }));
      },
      extras(k) {
        const h = k.h;
        addChild(k.parts.torso, createNode({ position: { x: 0, y: 0.33 * h, z: -3 * k.u - 0.05 * h }, scale: { x: h, y: h, z: h }, geometry: packGeometry() }));
      }
    }
  });
})();

sources.midy-machete:
(() => {
  "use strict";
  const BL = window.BL;
  const { makeVox, voxelGeometry } = BL.models;
  const { createNode, addChild } = BL.scene;
  const SKIN = "#d98b47", RED = "#ff2438", RED_CORE = "#fff4ee", WHITE = "#fff3f0", PINK = "#ffb3b6", LID = "#a8643a";
  const GOLD = "#f2b523", GOLD_HI = "#ffd768", GOLD_DK = "#c4861a", ORANGE = "#f7931a";
  const TOP = "#1a171b", SHORTS = "#2f3a3a", LEATHER = "#6a4424", BOOT = "#17131a", SOLE = "#8a4f1c";
  const HAIR = ["#241612", "#33211a", "#4a3024"];
  const BROW = "#2a1610", LIPS = "#5a2a1c", BLUSH = "#d47b40";
  const BTC = ["01010", "11110", "10001", "11110", "10001", "11110", "01010"];
