          H.poly(g, [on(-a, y0, 1, lift), on(a, y0, 1, lift), on(b, y1, 1, lift), on(-b, y1, 1, lift)], SKIN, [0, 0.4, 1]);
          if (b < WIDE) for (const e of [-1, 1]) H.poly(g, [on(e * a, y0, 1, lift), on(e * WIDE, y0, 1, lift), on(e * WIDE, y1, 1, lift), on(e * b, y1, 1, lift)], SKIN, [e, 0.4, 1]);
        }
        const pw = 0.26, ph = 0.232, top = 6.93, d = OFF + 0.04;
        eachMark((c, r) => {
          const x0 = (c - 2.5) * pw, y1 = top - r * ph;
          H.poly(g, [on(x0, y1 - ph, 1, d), on(x0 + pw, y1 - ph, 1, d), on(x0 + pw, y1, 1, d), on(x0, y1, 1, d)], GOLD, [0, 0, 1]);
        });
        H.loft(g, [shell(S.low + 0.02, 0.015), [S.low - 0.24, 2.9, 1.53, 0.5, 0, -0.03]], SHORTS, [false, true]);
        const B0 = 1.2, B1 = 2.5, BY = (B0 + B1) / 2;
        H.loft(g, [shell(B0 - 0.02, 0), shell(B0, 0.1), shell(B1, 0.1), shell(B1 + 0.02, 0)], LEATHER, [false, false]);
        const z0 = S.face(0, B0, 1) * tuck(B0) + 0.1, lean = (S.face(0, B1, 1) * tuck(B1) + 0.1 - z0) / (B1 - B0), nl = Math.hypot(lean, 1), out = [0, -lean / nl, 1 / nl];
        const plate = (w, t, c, up, deep, keep, ...ink) => H.slab(g, H.rect(-w, w, BY - t, BY + t, 0, c).map(([x, y]) => [x, y + out[1] * up, z0 + (y - B0) * lean + out[2] * up]), out, deep, keep, ...ink);
        plate(0.9, 0.8, 0.12, 0, 0.22, 0.94, GOLD, GOLD_DK);
        plate(0.55, 0.47, 0.06, 0.22, 0.02, 1, "#3b2413");
        plate(0.22, 0.19, 0.04, 0.24, 0.07, 0.9, GOLD_HI, GOLD);
        body.torso = M.merge(body.torso, H.scaled(g, u));
        const cuff = M.geometry(), bands = M.geometry();
        H.loft(cuff, [[-3.92, 0.84, 0.86, 0.3], [-3.76, 1.03, 1.05, 0.36], [-3.02, 1.07, 1.09, 0.36], [-2.86, 0.92, 0.95, 0.32]], [GOLD_DK, GOLD, GOLD_HI]);
        const band = "#2a242c";
        H.loft(bands, [[0.1, 1.36, 1.46, 0.42], [-0.96, 1.38, 1.48, 0.42], [-1.02, 1.31, 1.41, 0.4]], SHORTS, [false, false]);
        H.loft(bands, [[-3.95, 1.2, 1.31, 0.38, 0, 0.05], [-3.25, 1.15, 1.26, 0.38, 0, 0.07]], BOOT);
        H.loft(bands, [[-4.5, 1.33, 1.43, 0.4], [-3.95, 1.33, 1.43, 0.4]], band);
        H.loft(bands, [[-5.55, 1.31, 1.45, 0.4, 0, -0.03], [-5.05, 1.31, 1.43, 0.4]], band);
        H.loft(bands, [[-5.05, 1.21, 1.31, 0.355], [-4.5, 1.21, 1.31, 0.355]], "#e0851c", [false, false]);
        H.slab(bands, H.rect(-0.4, 0.4, -5.48, -5.12, 1.44, 0.05), H.FRONT, 0.12, 0.9, GOLD, GOLD_DK);
        H.loft(bands, [[-7 - SOLES, 1.26, 2.16, 0.35, 0, 0.6], [-6.68, 1.26, 2.16, 0.37, 0, 0.6]], [SOLE]);
        H.scaled(cuff, u); H.scaled(bands, u);
        for (const key of ["forearm", "forearmL"]) if (body[key]) body[key] = M.merge(body[key], cuff);
        for (const key of ["leg", "legL"]) if (body[key]) body[key] = M.merge(body[key], bands);
        return { ...body, headOpen: head(false), headClosed: head(true) };
      },
      crown(k, v) {
        const tones = HAIR.map((hex) => k.color(hex));
        mane((x, y, z, t) => v.set(x, y, z, tones[t]), (x, y, z) => v.set(x, y, z, k.P.skin));
      },
      eyes(k, v) {
        const red = k.color(RED), core = k.color(RED_CORE);
        for (const [x0, x1] of [[1, 2], [4, 5]]) for (let x = x0; x <= x1; x++) {
          v.set(x, 3, 5, x === 2 || x === 4 ? core : red);
          k.eyeCells.push([x, 3]);
        }
        k.headEmissive = { [red]: 1, [core]: 1.4 };
        k.lid = k.color(LID);
        return true;
      },
      mark(k, v) {
        const brow = k.color(BROW), lips = k.color(LIPS), gold = k.color(GOLD);
        for (const [x, y] of [[1, 5], [2, 4], [5, 5], [4, 4]]) v.set(x, y, 6, brow);
        for (const x of [2, 3, 4]) v.set(x, 1, 6, lips);
        for (const x of [-1, 7]) v.set(x, 1, 5, gold);
      },
      hatNodes(k) {
        const u = k.u, s = modelled() ? HEAD : 1, low = modelled() ? u * (s - NECK) : 0, size = { x: s, y: s, z: s };
        addChild(k.parts.head, createNode({ position: { x: 0, y: -low, z: 0 }, scale: size, geometry: crownGeometry(u) }));
        addChild(k.parts.head, createNode({ position: { x: 0, y: 9.7 * u * s - low, z: 3.5 * u * s }, scale: size, geometry: coinGeometry(u) }));
      },
      extras(k) {
        const h = k.h, u = k.u, bag = 0.67, big = 1.2;
        const up = modelled() ? SOLES * u : 0;
        k.root.position.y += up;
        const dog = k.parts.dog = createNode({ position: { x: 0.58 * h, y: -k.legH - up, z: -0.25 * h }, scale: { x: big, y: big, z: big }, geometry: dogGeometry(u) });
        const limb = (part, x, y, z) => { const n = createNode({ position: { x: x * u, y: y * u, z: z * u }, geometry: dogGeometry(u, part) }); addChild(dog, n); return n; };
        addChild(dog, createNode({ geometry: dogDetail(u) }));
        dog.legs = [[-0.75, 1.5], [0.75, 1.5], [-0.75, -2.5], [0.75, -2.5]].map(([x, z]) => limb("leg", x, 2, z));
        dog.tail = limb("tail", 0, 3.5, -3);
        dog.packAt = { y: 4.5 * u, z: -1.5 * u, scale: 0.25 };
        addChild(k.root, dog);
        addChild(k.parts.torso, createNode({ position: { x: -3.25 * u, y: 1.9 * u, z: -0.25 * u }, rotation: { x: 0, y: -1.62, z: 0.12 }, scale: { x: bag, y: bag, z: bag }, geometry: bagGeometry(u) }));
      }
    }
  });
})();

sources.rules-without-rulers:
(() => {
  "use strict";
  const BL = window.BL;
  const { box, lathe, ring, merge, cached } = BL.models;
  const { createNode, addChild } = BL.scene;
  const topHatGeometry = cached(() => {
    const felt = "#1b1b1d";
    const brim = lathe({ profile: [[0, 0], [0.31, 0], [0.325, 0.02], [0.31, 0.04], [0, 0.04]], segments: 14, color: "#111113" });
    const crown = lathe({ profile: [[0.205, 0.03], [0.2, 0.16], [0.205, 0.3], [0.225, 0.42], [0.23, 0.46], [0, 0.46]], segments: 14, color: felt });
    const cross = [];
    for (let i = -2; i <= 2; i++) {
      cross.push(box({ w: 0.036, h: 0.036, d: 0.03, color: "#f2efe4", offset: { x: i * 0.036, y: 0.27 + i * 0.036, z: 0.207 } }));
      if (i) cross.push(box({ w: 0.036, h: 0.036, d: 0.03, color: "#f2efe4", offset: { x: i * 0.036, y: 0.27 - i * 0.036, z: 0.207 } }));
    }
    return merge(brim, crown, ring({ r: 0.21, thickness: 0.035, y: 0.075, segments: 14, color: "#d8892b" }), ...cross);
  });
  const PUMPKIN = "#e8862a", PUMPKIN_DK = "#cf6f1c", PUMPKIN_GLOW = "#ffc14d";
  BL.characters.add({
    handle: "rules-without-rulers",
    display: "genXbtc",
    joined: 1789801750,
    lastCommit: 1789954043,
    look: { portrait: { min: [-1, -2, 0], max: [7, 7, 8] }, pumpkin: true, bald: true, cleanShaven: true, noBrow: true, noPupils: true, face: "none", skin: "#cfc8b4", hair: "#151515", fur: "#141414", height: 1.16 },
    voice: {
      poke: "POWER OVERWHELMING",
      idle: ["Shut up you larp", "Rules Without Rulers"]
    },
    dress: {
      model(k, wear) {
        const H = BL.heroBody, body = wear(), S = H.trunk(false), geo = BL.models.geometry(), STEPS = 10, HALF = 0.36, OUT = [0, 0, -1];
        const top = S.top - 0.6, foot = S.belt + 0.45, corner = (y) => { const [hx, , cut] = S.ring(y); return hx - cut - 0.16; };
        const strap = "#f4f1e8", bound = "#c9c3b0", stitch = "#8f8875", steel = "#a8adb5", steelDk = "#6d727a";
        for (const side of [-1, 1]) {
          const x1 = side * corner(top), x0 = -side * corner(foot), length = Math.hypot(x1 - x0, top - foot), nx = -(top - foot) / length * HALF, ny = (x1 - x0) / length * HALF;
          const at = (t, s, lift) => { const y = foot + (top - foot) * t + ny * s; return [x0 + (x1 - x0) * t + nx * s, y, S.back(y) - lift]; };
          const run = (t0, t1, s0, s1, lift) => [at(t0, s0, lift), at(t0, s1, lift), at(t1, s1, lift), at(t1, s0, lift)];
          for (let i = 0; i < STEPS; i++) {
            const t0 = i / STEPS, t1 = (i + 1) / STEPS;
            H.slab(geo, run(t0, t1, -1, 1, 0.01), OUT, 0.08, 1, strap, bound);
            for (const [s0, s1] of [[-1, -0.72], [0.72, 1]]) H.poly(geo, run(t0, t1, s0, s1, 0.095), bound, OUT);
            H.poly(geo, run(t0 + 0.03, t0 + 0.07, -0.14, 0.14, 0.095), stitch, OUT);
          }
          for (const t of [0.035, 0.965]) {
            H.slab(geo, run(t - 0.022, t + 0.022, -0.42, 0.42, 0.09), OUT, 0.07, 0.7, steel, steelDk);
          }
        }
        const mid = (top + foot) / 2, pin = S.back(mid) - 0.1;
        H.slab(geo, [[0, mid + 0.95, pin], [0.72, mid, pin], [0, mid - 0.95, pin], [-0.72, mid, pin]], OUT, 0.1, 0.78, "#e89423", "#b86f12");
        H.slab(geo, H.rect(-0.17, 0.17, mid - 0.17, mid + 0.17, pin - 0.1, 0.06), OUT, 0.07, 0.7, steel, steelDk);
        body.torso = merge(body.torso, H.scaled(geo, k.u));
        return body;
      },
      torso(k, v) {
        const P = k.P, orange = k.color("#e89423");
        v.fill(0, 8, 0, 7, 0, 5, k.leopard);
        for (const ry of [1, 3, 5]) v.fill(1, 7, ry, ry, 5, 5, k.skinJ);
        v.fill(4, 4, 1, 6, 5, 5, k.skinJ);
        v.fill(3, 5, 4, 7, 5, 5, k.jit(P.white, P.skin, 0.3));
        v.fill(6, 7, 5, 6, 5, 5, orange);
        v.set(7, 6, 5, P.spot);
        if (BL.models.STYLE !== "R") for (let i = 0; i <= 6; i++) {
          v.set(1 + i, 7 - i, 0, P.white);
          v.set(7 - i, 7 - i, 0, P.white);
        }
        const hide = k.color("#c8923a"), spot = k.color("#4a2f16");
        k.loin = [hide, spot];
        for (let x = 0; x <= 8; x++) for (let z = 0; z <= 5; z++) for (const y of [0, 1]) {
          if (x === 0 || x === 8 || z === 0 || z === 5) v.set(x, y, z, (x * 3 + y * 5 + z * 7) % 6 === 0 ? spot : hide);
        }
      },
      skull(k, v) {
        const pumpkin = k.color(PUMPKIN), pumpkinDk = k.color(PUMPKIN_DK);
        v.fill(-1, 7, 0, 7, -1, 5, (x) => (x + 9) % 3 ? pumpkin : pumpkinDk);
        for (let x = -1; x <= 7; x++) {
          for (let z = -1; z <= 5; z++) {
            if (x === -1 || x === 7 || z === -1 || z === 5) {
              v.del(x, 7, z);
              v.del(x, 0, z);
            }
          }
        }
        return true;
      },
      eyes(k, v) {
        const glow = k.color(PUMPKIN_GLOW);
        for (const [ex, ey] of [[1, 4], [2, 4], [2, 5], [4, 4], [5, 4], [4, 5]]) {
          v.set(ex, ey, 5, glow);
          k.eyeCells.push([ex, ey]);
        }
        v.set(3, 3, 5, glow);
        v.fill(0, 6, 2, 2, 5, 5, glow);
        v.set(2, 1, 5, glow);
        v.set(4, 1, 5, glow);
        k.headEmissive = { [glow]: 1 };
        k.lid = k.color(PUMPKIN_DK);
        return true;
      },
      hatNodes(k) {
        const h = k.h, u = k.u;
        addChild(k.parts.head, createNode({ position: { x: 0, y: 7.5 * u, z: 0 }, rotation: { x: 0, y: 0, z: 0.06 }, scale: { x: h, y: h, z: h }, geometry: topHatGeometry(), portraitHidden: true }));
      }
    }
  });
})();

sources.timechainb:
(() => {
  "use strict";
  const BL = window.BL;
  const { makeVox, voxelGeometry } = BL.models;
  const { createNode, addChild } = BL.scene;
  const { hexToRgb } = BL.math;
  const AXE = BL.models.STYLE === "R";
  const staffVoxels = (rand) => {
    const v = makeVox();
    const woodJ = () => rand() < 0.2 ? 1 : 0;
    v.fill(0, 0, -2, 15, 0, 0, woodJ);
    for (const y of [3, 8, 12]) v.set(rand() < 0.5 ? -1 : 1, y, 0, 1);
    for (const [y, z] of [[16, 0], [17, 1], [17, 2], [16, 3], [15, 3]]) v.set(AXE ? -z : 0, y, AXE ? 0 : z, woodJ());
    return v;
  };
  const LION_PALETTE = [hexToRgb("#d4a04a"), hexToRgb("#bd8b38"), hexToRgb("#a5602a"), hexToRgb("#7d4520"), hexToRgb("#ecc98a"), hexToRgb("#141414"),
    hexToRgb("#f2b33d"), hexToRgb("#3b241a")];
  const LION_U = 0.04, L = { fur: 0, furDk: 1, mane: 2, maneDk: 3, cream: 4, black: 5, amber: 6, nose: 7 };
  const lionBody = (rand) => {
    const v = makeVox();
    const fur = () => rand() < 0.15 ? L.furDk : L.fur;
    const mane = () => rand() < 0.35 ? L.maneDk : L.mane;
    v.fill(-4, 3, 6, 12, -7, 7, fur);
    v.fill(-2, 1, 6, 6, -5, 5, L.cream);
    v.fill(-4, 3, 10, 16, 6, 11, fur);
    v.fill(-7, 6, 6, 20, 4, 10, (x, y, z) => {
      const dx = (x + 0.5) / 7.2, dy = (y - 13) / 7.2, ring = dx * dx + dy * dy <= 1;
      if (!ring) return null;
      const face = x >= -4 && x <= 3 && y >= 9 && y <= 16;
      return face && z > 7 ? null : mane();
    });
    v.fill(-3, 2, 7, 9, 9, 11, mane);
    v.fill(-3, 2, 15, 15, 11, 11, L.furDk);
    for (const [x, pupil] of [[-3, -2], [2, 1]]) { v.set(x, 14, 11, L.amber); v.set(pupil, 14, 11, L.black); }
    v.fill(-3, 2, 10, 12, 12, 12, L.cream);
    v.fill(-2, 1, 13, 13, 12, 12, L.nose);
    v.fill(-1, 0, 12, 12, 12, 13, L.nose);
    v.fill(-1, 0, 11, 11, 12, 12, L.nose);
    v.set(-2, 10, 12, L.nose);
    v.set(1, 10, 12, L.nose);
    for (const x of [-3, 2]) v.set(x, 11, 12, L.furDk);
    v.fill(-2, 1, 9, 9, 11, 12, L.cream);
    for (const x of [-5, 3]) {
      v.fill(x, x + 1, 19, 20, 9, 10, fur);
      v.fill(x, x + 1, 19, 19, 10, 10, L.maneDk);
    }
    return v;
  };
  const lionLeg = () => {
    const v = makeVox();
    v.fill(-1, 1, -6, -1, -1, 1, (x, y) => y === -6 ? L.furDk : L.fur);
    return v;
  };
  const lionTail = () => {
    const v = makeVox();
    for (const [y, z] of [[0, 0], [0, -1], [-1, -2], [-2, -3], [-3, -4], [-4, -4], [-5, -4]]) v.set(0, y, z, L.fur);
    v.fill(-1, 1, -7, -6, -5, -3, (x, y, z) => (x + y + z) % 2 ? L.maneDk : L.mane);
    return v;
  };
  const lionCub = (k) => {
    const U = LION_U, h = k.h, centred = { x: -U / 2, y: 0, z: -U / 2 };
    const node = createNode({ position: { x: 0.7 * h, y: -k.legH, z: -0.2 * h }, geometry: voxelGeometry(lionBody(k.rand), { unit: U, palette: LION_PALETTE }) });
    const leg = voxelGeometry(lionLeg(), { unit: U, palette: LION_PALETTE, origin: centred });
    node.legs = [[-2.5, 5.5], [2.5, 5.5], [-2.5, -4.5], [2.5, -4.5]].map(([x, z]) => {
      const n = createNode({ position: { x: x * U, y: 6 * U, z: z * U }, geometry: leg });
      addChild(node, n);
      return n;
    });
    node.tail = createNode({ position: { x: 0, y: 11 * U, z: -7.5 * U }, geometry: voxelGeometry(lionTail(), { unit: U, palette: LION_PALETTE, origin: { x: -U / 2, y: -U / 2, z: -U / 2 } }) });
    addChild(node, node.tail);
    node.packAt = { y: 13 * U, z: -5.5 * U, scale: 0.56 };
    return node;
  };
  BL.characters.add({
    handle: "timechainb",
    joined: 1788800921,
    lastCommit: 1788171200,
    look: { portrait: { min: [-1, -2, 0], max: [7, 11, 8] }, stoneAxe: AXE, hairless: true, skin: "#b8703c", hair: "#33200f" },
    dress: {
      club: (k) => AXE ? { voxels: staffVoxels(k.rand), rest: { x: 0.24, z: 0 }, carry: { x: 0.95, z: 0 } } : { voxels: staffVoxels(k.rand), rest: { x: 0.2, z: 0 } },
      crown(k, v) {
        const hair = k.color("#33200f"), hairDk = k.color("#2b1b0d");
        const curl = (x, y, z) => (x + y + z) % 2 ? hairDk : hair;
        v.fill(-1, 7, -4, 5, -2, -1, curl);
        v.fill(-1, -1, -4, 5, 0, 2, curl);
        v.fill(7, 7, -4, 5, 0, 2, curl);
        v.fill(0, 6, 0, 1, 5, 7, curl);
        v.fill(0, 6, -2, -1, 5, 8, curl);
        v.fill(1, 5, -5, -3, 6, 8, curl);
        v.fill(2, 4, -7, -6, 7, 8, curl);
        v.set(3, -8, 8, hairDk);
      },
      hat(k, v) {
        const gold = k.color("#d4a83a"), goldDk = k.color("#9c7a22");
        v.fill(-1, 7, 6, 8, -1, 6, (x, y) => y === 7 ? gold : goldDk);
        v.fill(0, 6, 9, 9, 0, 5, gold);
        v.fill(1, 5, 10, 10, 1, 4, goldDk);
        v.fill(2, 4, 11, 11, 2, 3, gold);
      },
      extras(k) {
        k.parts.dog = lionCub(k);
        addChild(k.root, k.parts.dog);
      }
    }
  });
})();
